// v1_calc.js - Basic calculator module with add, sub, div functions

// Add function
function add(a, b) {
    return a + b;
}

// Subtract function
function sub(a, b) {
    return a - b;
}

// Divide function with divide-by-zero check
function div(a, b) {
    if (b === 0) {
        throw new Error("Division by zero");
    }
    return a / b;
}

// Export the functions
module.exports = { add, sub, div };

// Self-checks
console.log("Running self-checks for v1_calc.js...");

try {
    // Test add function
    const addResult = add(5, 3);
    console.log(`add(5, 3) = ${addResult}`);
    if (addResult !== 8) {
        throw new Error("add function failed");
    }

    // Test sub function
    const subResult = sub(5, 3);
    console.log(`sub(5, 3) = ${subResult}`);
    if (subResult !== 2) {
        throw new Error("sub function failed");
    }

    // Test div function with normal case
    const divResult = div(10, 2);
    console.log(`div(10, 2) = ${divResult}`);
    if (divResult !== 5) {
        throw new Error("div function failed");
    }

    // Test div function with zero division
    try {
        div(10, 0);
        console.log("ERROR: div(10, 0) should have thrown an error");
    } catch (e) {
        console.log("div(10, 0) correctly threw error:", e.message);
    }

    console.log("All self-checks passed!");

} catch (error) {
    console.error("Self-check failed:", error.message);
    process.exit(1);
}
```

