```javascript
function greet(name) {
    if (typeof name !== 'string') {
        throw new Error('Name must be a string');
    }
    return `Hello, ${name}!`;
}

function farewell(name) {
    if (typeof name !== 'string') {
        throw new Error('Name must be a string');
    }
    return `Goodbye, ${name}!`;
}

module.exports = { greet, farewell };
