// Vector addition function
function add(a, b) {
    if (a === undefined || b === undefined) {
        throw new Error("Vector addition requires two arguments");
    }
    if (typeof a !== 'object' || a === null || !('x' in a) || !('y' in a)) {
        throw new Error("First argument must be an object with x and y properties");
    }
    if (typeof b !== 'object' || b === null || !('x' in b) || !('y' in b)) {
        throw new Error("Second argument must be an object with x and y properties");
    }
    return {x: a.x + b.x, y: a.y + b.y};
}

// Self-check
const result = add({x:1,y:2},{x:3,y:4});
if (result.x !== 4 || result.y !== 6) {
    throw new Error(`Vector addition failed: expected {x:4,y:6}, got {x:${result.x},y:${result.y}}`);
}

// Vector subtraction function
function sub(a, b) {
    return {x: a.x - b.x, y: a.y - b.y};
}

// Self-check for subtraction
const subResult = sub({x:5,y:6},{x:2,y:3});
if (subResult.x !== 3 || subResult.y !== 3) {
    throw new Error(`Vector subtraction failed: expected {x:3,y:3}, got {x:${subResult.x},y:${subResult.y}}`);
}

// Vector length (magnitude) function
function len(v) {
    return Math.sqrt(v.x * v.x + v.y * v.y);
}

// Self-check for length
const lenResult = len({x:3,y:4});
if (lenResult !== 5) {
    throw new Error(`Vector length failed: expected 5, got ${lenResult}`);
}

// Export the functions
module.exports = { add, sub, len };
```

