function slug(s) {
  if (typeof s !== 'string') {
    throw new TypeError('Input must be a string');
  }
  return s.toLowerCase()
    .replace(/\s+/g, '-')
    .replace(/[^a-z0-9-]/g, '');
}

function title(s) {
  if (typeof s !== 'string') {
    throw new TypeError('Input must be a string');
  }
  return s.split(/\s+/)
    .filter(word => word.length > 0)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
}

module.exports = { slug, title };
```

