  // Validate inputs
  if (typeof a !== 'number' || isNaN(a)) {
    throw new Error('First argument must be a number');
  }
  if (typeof b !== 'number' || isNaN(b)) {
    throw new Error('Second argument must be a number');
  }

  return a * b;
}

// Export functions
module.exports = { add, mul };
