<!DOCTYPE html>
<html>
<head>
    <title>Phaser 3 Game</title>
    <script src="https://cdn.jsdelivr.net/npm/phaser@3.60.0/dist/phaser.min.js"></script>
</head>
<body>
    <script>
        var config = {
            type: Phaser.AUTO,
            width: 800,
            height: 600,
            physics: {
                default: 'arcade',
                arcade: {
                    gravity: { y: 0 },
                    debug: false
                }
            },
            scene: {
                preload: preload,
                create: create,
                update: update
            }
        };

        var game = new Phaser.Game(config);
        var player;
        var cursors;
        var coins;
        var score = 0;
        var scoreText;

        function preload() {
            this.load.image('player', 'assets/player.png');
            this.load.image('coin', 'assets/coin.png');
        }

        function create() {
            // Create a sprite at the center of the screen
            player = this.physics.add.sprite(400, 300, 'player');
            player.setCollideWorldBounds(true);

            // Create keyboard input
            cursors = this.input.keyboard.createCursorKeys();

            // Create collectible items
            coins = this.physics.add.group();
            score = 0;
            scoreText = this.add.text(16, 16, 'Score: 0', { fontSize: '32px', fill: '#000' });

            // Create some coins
            for (let i = 0; i < 5; i++) {
                const x = Phaser.Math.Between(50, 750);
                const y = Phaser.Math.Between(50, 550);
                const coin = coins.create(x, y, 'coin');
                coin.setBounce(0.2);
                coin.setCollideWorldBounds(true);
            }

            // Set up collision between player and coins
            this.physics.add.overlap(player, coins, collectCoin, null, this);
        }

        function update() {
            // Move the player based on cursor keys
            if (cursors.left.isDown) {
                player.setVelocityX(-160);
            } else if (cursors.right.isDown) {
                player.setVelocityX(160);
            } else {
                player.setVelocityX(0);
            }

            if (cursors.up.isDown) {
                player.setVelocityY(-160);
            } else if (cursors.down.isDown) {
                player.setVelocityY(160);
            } else {
                player.setVelocityY(0);
            }
        }

        function collectCoin(player, coin) {
            // Remove the coin from the game
            coin.disableBody(true, true);

            // Update score
            score += 10;
            scoreText.setText('Score: ' + score);

            // Check if all coins are collected
            if (coins.countActive(true) === 0) {
                this.add.text(400, 300, 'You Win!', { fontSize: '64px', fill: '#00ff00' }).setOrigin(0.5);
            }
        }
    </script>
</body>
</html>
