// Export slug function
function slug(s) {
    // Validate input
    if (typeof s !== 'string') {
        throw new Error('Input must be a string');
    }

    // Convert to lowercase, replace non-alphanumeric characters with hyphens, 
    // remove leading/trailing hyphens, and collapse multiple hyphens
    return s.toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
        .replace(/-+/g, '-');
}

// Export title function
function title(s) {
    // Validate input
    if (typeof s !== 'string') {
        throw new Error('Input must be a string');
    }

    // Split by spaces, capitalize first letter of each word, join back with spaces
    return s.split(' ')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
        .join(' ');
}

module.exports = { slug, title };
```

