// Zip two arrays together
function zip(a, b) {
    const result = [];
    const len = Math.min(a.length, b.length);
    for (let i = 0; i < len; i++) {
        result.push([a[i], b[i]]);
    }
    return result;
}

// Generate a range of numbers
function range(n) {
    const result = [];
    for (let i = 0; i < n; i++) {
        result.push(i);
